UPDATE public.productos
SET
  nombre_es = 'Mamógrafo digital DM166 Series Angell con tomosíntesis 3D y CESM',
  nombre_en = 'Angell DM166 Series Digital Mammography with 3D Tomosynthesis and CESM',
  descripcion_corta_es = 'Mamógrafo digital Angell configurable con tomosíntesis 3D de ángulo amplio, detector de alta resolución y opción CESM',
  descripcion_corta_en = 'Configurable Angell digital mammography system with wide-angle 3D tomosynthesis, high-resolution detector and optional CESM',
  descripcion_larga_es = 'El DM166 Series aborda dos retos frecuentes de la mamografía: la superposición del tejido glandular que puede ocultar masas o distorsiones y la necesidad de mantener un flujo cómodo, reproducible y seguro. Según configuración, integra mamografía 2D, tomosíntesis DBT de 50° con adquisición de 25 proyecciones y salida de cortes de 1 mm, además de versiones 3D CESM para combinar información anatómica y realce con contraste. Sus detectores Angell —CSI de 77 μm o CMOS de 49,8 μm en configuraciones de la serie—, control automático de exposición, colimación inteligente y compresión flexible permiten adaptar el protocolo al tamaño y densidad mamaria. El brazo C, la memoria de posicionamiento MLO, la liberación de emergencia y el rango vertical de hasta 840 mm ayudan a resolver limitaciones de posicionamiento, incluidas pacientes con movilidad reducida o en silla de ruedas. La configuración final, accesorios, software y prestaciones clínicas deben confirmarse en la cotización y documentación vigente del fabricante.',
  descripcion_larga_en = 'The DM166 Series addresses two recurring mammography challenges: overlapping glandular tissue that can hide masses or architectural distortion, and the need for a comfortable, reproducible and safe workflow. Depending on configuration, it combines 2D mammography, 50° DBT wide-angle tomosynthesis with 25 projections and 1 mm slice output, plus 3D CESM versions that combine anatomical and contrast-enhancement information. Angell detectors —77 μm CSI or 49.8 μm CMOS in different series configurations—, automatic exposure control, intelligent collimation and flexible compression help adapt protocols to breast size and density. The C-arm, MLO positioning memory, emergency release and up to 840 mm vertical travel help solve positioning limitations, including patients with reduced mobility or using a wheelchair. Final configuration, accessories, software and clinical features must be confirmed in the quotation and current manufacturer documentation.',
  especificaciones = $$[
    {"clave":"Tomosíntesis DBT","grupo":"Tecnología de imagen","valor":"Ángulo amplio de 50° (±25°), 25 exposiciones y cortes estándar de 1 mm; grosor configurable según versión"},
    {"clave":"Detector","grupo":"Tecnología de imagen","valor":"Configuraciones con detector CSI de 77 μm y 4096×3072 píxeles o CMOS de 49,8 μm y 4489×5663 píxeles"},
    {"clave":"Modalidades","grupo":"Tecnología de imagen","valor":"Mamografía 2D, DBT 3D, combinación TOMO + 2D y CESM 3D opcional según configuración"},
    {"clave":"Campo de imagen","grupo":"Cobertura anatómica","valor":"Panel de campo completo de aproximadamente 24×30 cm; validar medida exacta por versión"},
    {"clave":"Posicionamiento","grupo":"Ergonomía y flujo","valor":"Brazo C con rotación amplia, memoria de posición MLO, diseño isocéntrico y rango vertical de hasta 840 mm"},
    {"clave":"Compresión","grupo":"Ergonomía y flujo","valor":"Compresión flexible, placas transparentes, spot compression, reconocimiento automático y liberación de emergencia"},
    {"clave":"Gestión de dosis","grupo":"Seguridad radiológica","valor":"AEC, colimación eléctrica inteligente y ajuste del campo de luz para reducir exposiciones innecesarias"},
    {"clave":"Procesamiento","grupo":"Software y lectura","valor":"Reconstrucción DBT, reproducción y extracción de cuadros; CESM y funciones asistidas por IA disponibles según configuración"}
  ]$$::jsonb,
  ficha_pdf = '/assets/productos/radiologia/dm166-angell-datasheet.pdf',
  atributos = atributos || $$ {
    "marca":"Angell Technology",
    "fabricante":"Angell Technology",
    "valor_es":"Tomosíntesis 3D de ángulo amplio, posicionamiento inclusivo y CESM configurable para ampliar la capacidad diagnóstica de una unidad de mamografía.",
    "valor_en":"Wide-angle 3D tomosynthesis, inclusive positioning and configurable CESM to expand a mammography unit's diagnostic capability.",
    "beneficios_es":[
      "Reduce el problema de la superposición glandular: la tomosíntesis de 50° aporta mayor separación en profundidad para localizar masas, distorsiones arquitecturales y lesiones de bajo contraste.",
      "Permite diseñar una ruta diagnóstica escalable: mamografía 2D, DBT, TOMO + 2D y CESM 3D pueden definirse según el servicio, el protocolo y el presupuesto institucional.",
      "Mejora el posicionamiento en pacientes difíciles: memoria MLO, movimiento amplio del brazo C y hasta 840 mm de recorrido vertical facilitan la atención de personas con movilidad limitada o en silla de ruedas.",
      "Protege el flujo de trabajo del tecnólogo: AEC, colimación inteligente, reconocimiento del compresor, pantalla de doble lectura y placas de compresión flexibles reducen ajustes y repeticiones.",
      "Frente a un sistema 2D aislado, la opción CESM integra información anatómica y de realce en una plataforma de mamografía, útil para protocolos de mama densa y valoración preoperatoria cuando esté indicada y configurada."
    ],
    "beneficios_en":[
      "Reduces glandular overlap: 50° tomosynthesis provides greater depth separation to localize masses, architectural distortion and low-contrast lesions.",
      "Builds a scalable diagnostic pathway: 2D mammography, DBT, TOMO + 2D and 3D CESM can be specified according to the service, protocol and institutional budget.",
      "Improves positioning for difficult examinations: MLO memory, wide C-arm movement and up to 840 mm vertical travel support patients with reduced mobility or using a wheelchair.",
      "Protects technologist workflow: AEC, intelligent collimation, compressor recognition, dual-screen reading and flexible compression plates help reduce adjustments and repeats.",
      "Compared with a standalone 2D system, the CESM option combines anatomical and enhancement information on a mammography platform for dense-breast and preoperative protocols when clinically indicated and configured."
    ],
    "preguntas_frecuentes_es":[
      {"q":"¿Qué versiones del DM166 se pueden configurar?","a":"La documentación Angell contempla configuraciones 2D, DBT 3D, TOMO + 2D y versiones 3D CESM. El detector, software, placas, accesorios y funciones opcionales se confirman para cada cotización."},
      {"q":"¿Qué ventaja aporta el ángulo de 50° en tomosíntesis?","a":"El barrido amplio de ±25° y sus 25 exposiciones mejoran la separación en el eje Z frente a sistemas de ángulo más estrecho, ayudando a analizar tejido superpuesto. La interpretación corresponde al especialista."},
      {"q":"¿Puede atender pacientes en silla de ruedas?","a":"La documentación del fabricante indica un rango vertical de hasta 840 mm y posicionamiento diseñado para distintos tipos corporales, incluida la mamografía en silla de ruedas, sujeto a protocolo y configuración instalada."},
      {"q":"¿El equipo incorpora CESM?","a":"CESM es una opción de la familia DM166 Ultra/3D Energy Spectrum. Requiere confirmar hardware, software, contraste, protocolos y requisitos regulatorios antes de la compra."},
      {"q":"¿El PDF contiene todas las especificaciones finales?","a":"No necesariamente. El documento es genérico: algunos equipos son configurables y sus especificaciones pueden cambiar. I-ME valida la configuración vigente en la cotización formal."}
    ],
    "preguntas_frecuentes_en":[
      {"q":"Which DM166 configurations are available?","a":"Angell documentation describes 2D, 3D DBT, TOMO + 2D and 3D CESM configurations. Detector, software, plates, accessories and optional functions are confirmed for each quotation."},
      {"q":"What does the 50° tomosynthesis angle add?","a":"The ±25° sweep and 25 exposures improve Z-axis separation compared with narrower-angle systems, helping analyze overlapping tissue. Interpretation remains the responsibility of the specialist."},
      {"q":"Can it examine wheelchair patients?","a":"Manufacturer documentation indicates up to 840 mm vertical travel and positioning for different body types, including wheelchair mammography, subject to protocol and installed configuration."},
      {"q":"Does the system include CESM?","a":"CESM is an option in the DM166 Ultra/3D Energy Spectrum family. Hardware, software, contrast protocols and regulatory requirements must be confirmed before purchase."},
      {"q":"Does the PDF contain final specifications?","a":"Not necessarily. It is a generic document: configurable equipment can differ from the specifications shown. I-ME confirms the current configuration in the formal quotation."}
    ],
    "seo_keywords_es":["mamógrafo digital DM166","tomosíntesis 3D 50 grados","mamografía CESM Colombia","mamógrafo para mama densa","mamógrafo digital Angell"],
    "seo_keywords_en":["DM166 digital mammography","50 degree 3D tomosynthesis","CESM mammography Colombia","dense breast mammography","Angell mammography system"]
  } $$::jsonb
WHERE slug = 'mamografo-digital-dm166-series';

UPDATE public.productos
SET
  nombre_es = 'Sistema de telemando digital R/F Talent II DTP886 Angell',
  nombre_en = 'Angell Talent II DTP886 Digital R/F Remote-Control Table System',
  descripcion_corta_es = 'Sistema de telemando digital R/F de 80 kW para radiografía, fluoroscopia, estudios contrastados y tomosíntesis opcional',
  descripcion_corta_en = '80 kW digital R/F remote-control system for radiography, fluoroscopy, contrast studies and optional tomosynthesis',
  descripcion_larga_es = 'El Talent II DTP886 resuelve la fragmentación entre radiografía digital, fluoroscopia y estudios contrastados en servicios que necesitan una sala R/F versátil. Su generador Angell XDRP80 de 80 kW, detector dinámico HCP de 43×43 cm y mesa de telemando DC-DT-4 permiten cambiar entre adquisición estática y dinámica con control remoto. La mesa soporta hasta 200 kg, gira de -15° a +90°, ofrece movimientos laterales y verticales del tubo y dispone de posicionamiento de pie o tumbado con un clic. La estación TS-5 añade DICOM 3.0, worklist, adquisición de vídeo, stitching óseo, procesamiento y plantillas de informe. El módulo TOMO de barrido lineal amplio es opcional: puede alcanzar 1 mm de espesor, 1 mm de separación, hasta 300 capas y 1.100 mm de cobertura según la certificación y configuración contratada. La selección final de tubo, consola móvil, accesorios, software y opciones debe verificarse en la cotización.',
  descripcion_larga_en = 'The Talent II DTP886 addresses the fragmentation between digital radiography, fluoroscopy and contrast studies in facilities that need a versatile R/F room. Its 80 kW Angell XDRP80 generator, 43×43 cm HCP dynamic detector and DC-DT-4 remote-control table support seamless switching between static and dynamic acquisition. The table supports up to 200 kg, rotates from -15° to +90°, provides tube lateral and vertical movement, and offers one-click standing or lying positioning. The TS-5 workstation adds DICOM 3.0, worklist, video acquisition, bone stitching, image processing and report templates. The wide-range linear TOMO module is optional: it can reach 1 mm layer thickness, 1 mm spacing, up to 300 layers and 1,100 mm coverage, subject to certification and contracted configuration. Final tube, movable console, accessories, software and options must be verified in the quotation.',
  especificaciones = $$[
    {"clave":"Generador","grupo":"Generación de rayos X","valor":"Angell XDRP80, 80 kW; radiografía 40–150 kV y fluoroscopia 40–125 kV; 0,1–1.000 mAs; AEC y ABS"},
    {"clave":"Tubo de rayos X","grupo":"Generación de rayos X","valor":"Siemens SV150/40/80C-100_1; focos 0,6/1,0 mm; hasta 150 kV; capacidad térmica del ánodo 600 kHU"},
    {"clave":"Detector dinámico","grupo":"Tecnología de imagen","valor":"Angell HCP de panel plano con CsI, área 43×43 cm, matriz estática 3072×3072, 16 bits y resolución espacial estática 3,5 lp/mm"},
    {"clave":"Fluoroscopia","grupo":"Tecnología de imagen","valor":"Hasta 12 f/s en fluoroscopia pulsada y 30 f/s en fluoroscopia continua; preparación spot-film ≤0,8 s"},
    {"clave":"Mesa de telemando","grupo":"Posicionamiento","valor":"2.100×880×715 mm, desplazamiento lateral 250 mm, SID 1,15–1,8 m, rotación -15° a +90° y carga de hasta 200 kg"},
    {"clave":"Columna y tubo","grupo":"Posicionamiento","valor":"Columna ±35°, conjunto del tubo -90°/0°/+90°, brazo con desplazamiento lateral 1.300 mm y vertical 650 mm"},
    {"clave":"Estación de trabajo","grupo":"Software e integración","valor":"Angell TS-5 con DICOM 3.0, worklist, adquisición estática/dinámica, vídeo, stitching óseo, APR con al menos 1.350 programas y envío a PACS"},
    {"clave":"TOMO opcional","grupo":"Opciones","valor":"Barrido lineal de gran cobertura: espesor mínimo 1 mm, separación 1 mm, hasta 300 capas y cobertura máxima de 1.100 mm; validar certificación y disponibilidad"},
    {"clave":"Consola y seguridad","grupo":"Flujo de trabajo","valor":"Consola remota YKT-4, consola móvil YKT-4M opcional, bloqueo de exposición/fluoroscopia, intercomunicación y pedal giratorio 360°"}
  ]$$::jsonb,
  ficha_pdf = '/assets/productos/radiologia/talent-ii-angell-specifications.pdf',
  atributos = atributos || $$ {"marca":"Angell Technology","fabricante":"Angell Technology","valor_es":"Una plataforma R/F configurable para integrar radiografía digital, fluoroscopia y estudios contrastados con control remoto y conectividad DICOM.","valor_en":"A configurable R/F platform integrating digital radiography, fluoroscopy and contrast studies with remote control and DICOM connectivity.","beneficios_es":["Una sola sala cubre radiografía, fluoroscopia y estudios contrastados, reduciendo la necesidad de derivar pacientes entre equipos o modalidades separadas.","El control remoto y los interruptores de bloqueo de exposición ayudan a separar al operador del campo de radiación y a prevenir activaciones accidentales dentro del protocolo de seguridad institucional.","La mesa de 200 kg, el giro de -15° a +90° y el cambio de pie a tumbado con un clic permiten adaptar el estudio a pacientes y procedimientos con distintas posiciones.","El detector dinámico de 43×43 cm, la fluoroscopia de hasta 30 f/s y la preparación spot-film ≤0,8 s sostienen estudios dinámicos y contrastados con menos esperas entre adquisiciones.","DICOM 3.0, worklist, stitching óseo, APR y plantillas de informe conectan la adquisición con PACS y ayudan a estandarizar el flujo de radiología."],"beneficios_en":["One room covers radiography, fluoroscopy and contrast studies, reducing referrals between separate systems or modalities.","Remote operation and exposure-lock switches help keep the operator away from the radiation field and prevent accidental activation within the facility safety protocol.","The 200 kg table, -15° to +90° rotation and one-click standing-to-lying positioning adapt the examination to different patients and procedures.","The 43×43 cm dynamic detector, up to 30 f/s fluoroscopy and ≤0.8 s spot-film preparation support dynamic and contrast studies with less waiting between acquisitions.","DICOM 3.0, worklist, bone stitching, APR and report templates connect acquisition to PACS and help standardize radiology workflow."],"preguntas_frecuentes_es":[{"q":"¿Qué incluye el Talent II DTP886?","a":"La configuración de referencia incluye detector dinámico Angell HCP, generador XDRP80, tubo SV150/40, colimador, mesa DC-DT-4, consola YKT-4, estación TS-5, rejilla y accesorios. La consola móvil y TOMO son opciones."},{"q":"¿Qué estudios permite realizar?","a":"Radiografía digital, fluoroscopia, estudios gastrointestinales y urológicos contrastados, imágenes dinámicas, stitching óseo y otras aplicaciones definidas por el protocolo institucional."},{"q":"¿Qué significa que TOMO sea opcional?","a":"El módulo de tomosíntesis lineal no está incluido en todas las configuraciones. Sus capas, cobertura, software y certificación deben confirmarse antes de cerrar la compra."},{"q":"¿Se integra con PACS?","a":"La ficha indica compatibilidad DICOM 3.0, worklist y envío automático; la integración concreta depende de la red, PACS y configuración informática de la institución."},{"q":"¿Las cifras del PDF son definitivas?","a":"El PDF describe una configuración de referencia. Algunos equipos son configurables y pueden cambiar tubo, detector, consola, software y accesorios respecto al documento genérico; I-ME lo confirma en la cotización formal."}],"preguntas_frecuentes_en":[{"q":"What is included in the Talent II DTP886?","a":"The reference configuration includes the Angell HCP dynamic detector, XDRP80 generator, SV150/40 tube, collimator, DC-DT-4 table, YKT-4 console, TS-5 workstation, grid and accessories. The movable console and TOMO are optional."},{"q":"Which examinations can it perform?","a":"Digital radiography, fluoroscopy, gastrointestinal and urological contrast studies, dynamic imaging, bone stitching and other applications defined by the institution's protocol."},{"q":"What does optional TOMO mean?","a":"The linear tomosynthesis module is not included in every configuration. Layers, coverage, software and certification must be confirmed before purchase."},{"q":"Does it integrate with PACS?","a":"The sheet specifies DICOM 3.0, worklist and automatic sending; the actual integration depends on the institution's network, PACS and IT configuration."},{"q":"Are PDF figures final?","a":"The PDF describes a reference configuration. Equipment can be configurable, so tube, detector, console, software and accessories may differ from the generic document; I-ME confirms them in the formal quotation."}],"seo_keywords_es":["telemando digital Talent II","sala R/F radiología Colombia","mesa de fluoroscopia digital","radiografía y fluoroscopia DICOM","sistema R/F Angell"],"seo_keywords_en":["Talent II digital R/F","digital fluoroscopy room Colombia","remote control R/F table","DICOM radiography fluoroscopy","Angell R/F system"]} $$::jsonb
WHERE slug = 'telemando-digital-rf-talent-ii';

UPDATE public.productos
SET
  nombre_es = 'Sistema radiográfico 3D en carga WR-3D Angell Technology',
  nombre_en = 'Angell Technology WR-3D Weight-Bearing 3D Radiography System',
  descripcion_corta_es = 'Sistema CBCT de radiografía 3D en bipedestación para columna, pelvis y miembros inferiores con reconstrucción MPR, MIP y VR',
  descripcion_corta_en = 'Standing CBCT 3D radiography system for spine, pelvis and lower limbs with MPR, MIP and VR reconstruction',
  descripcion_larga_es = 'El WR-3D aporta imagen CBCT en bipedestación para resolver la superposición de la radiografía 2D y la pérdida de carga funcional de los estudios en decúbito. Combina radiografía 2D, fluoroscopia 2D y reconstrucción 3D para columna completa, pelvis, cadera, rodilla, tobillo y miembros inferiores. Ofrece FOV de hasta 350 mm, cobertura vertical de hasta 1.450 mm, adquisición regional aproximada de 25 segundos y reconstrucciones MPR, MIP y VR. Sus paquetes de medición pueden incluir Cobb 3D, HKA, ejes mecánicos, torsiones, flexión y espacios articulares. La documentación Angell indica una dosis aproximada del 10–20% frente a CT espiral convencional; módulos y mediciones son configurables.',
  descripcion_larga_en = 'WR-3D provides standing CBCT imaging to address 2D radiographic overlap and the loss of functional loading in supine studies. It combines 2D radiography, 2D fluoroscopy and 3D reconstruction for the full spine, pelvis, hip, knee, ankle and lower limbs. It offers up to 350 mm FOV, up to 1,450 mm vertical coverage, approximately 25-second regional acquisition and MPR, MIP and VR reconstructions. Measurement packages may include 3D Cobb, HKA, mechanical axes, torsion, flexion and joint spaces. Angell documentation indicates approximately 10–20% of conventional spiral CT dose; modules and measurements are configurable.',
  especificaciones = $$[
    {"clave":"Tecnología","grupo":"Adquisición","valor":"CBCT no isocéntrico con radiografía 2D, fluoroscopia 2D y reconstrucción 3D en carga"},
    {"clave":"Campo de visión","grupo":"Cobertura","valor":"Hasta 350 mm de FOV y hasta 1.450 mm en dirección cabeza-pies, según protocolo"},
    {"clave":"Adquisición","grupo":"Rendimiento","valor":"Aproximadamente 25 s para una región; el flujo de escaneo y reconstrucción puede rondar 3 minutos"},
    {"clave":"Reconstrucción","grupo":"Software","valor":"MPR, MIP y VR con mediciones automáticas disponibles por paquete"},
    {"clave":"Aplicaciones","grupo":"Anatomía","valor":"Columna completa, pelvis, cadera, miembros inferiores, rodilla, tobillo y vía aérea"},
    {"clave":"Dosis","grupo":"Seguridad radiológica","valor":"El fabricante indica aproximadamente 10–20% de la dosis de un CT espiral convencional; validar localmente"}
  ]$$::jsonb,
  ficha_pdf = '/assets/productos/radiologia/wr-3d-angell-brochure.pdf',
  atributos = atributos || $$ {"marca":"Angell Technology","fabricante":"Angell Technology","valor_es":"Tomografía 3D musculoesquelética en carga para evaluar alineación y deformidad con el paciente de pie.","valor_en":"Weight-bearing musculoskeletal 3D tomography for assessing alignment and deformity with the patient standing.","beneficios_es":["Muestra la deformidad en tres planos mientras el paciente está de pie, donde aparecen la carga, torsión y alineación funcionales.","Reduce la dependencia de proyecciones 2D y posicionamientos forzados para estudiar escoliosis, rodilla, pelvis y miembros inferiores.","Integra 2D, fluoroscopia y 3D en una plataforma, evitando fragmentar el flujo entre equipos para diferentes preguntas musculoesqueléticas.","Permite contratar paquetes de medición y reconstrucción según las necesidades del servicio, desde columna hasta planificación de miembro inferior.","La dosis orientativa publicada por Angell es inferior a la de un CT espiral convencional, siempre sujeta a protocolo, paciente y verificación local."],"beneficios_en":["Shows deformity in three planes while the patient is standing, where functional loading, torsion and alignment appear.","Reduces reliance on 2D projections and forced positioning for scoliosis, knee, pelvis and lower-limb assessment.","Integrates 2D, fluoroscopy and 3D on one platform, avoiding fragmented workflows across different musculoskeletal questions.","Measurement and reconstruction packages can be specified according to service needs, from spine to lower-limb planning.","Angell publishes an indicative dose below conventional spiral CT, always subject to protocol, patient and local verification."],"preguntas_frecuentes_es":[{"q":"¿Qué diferencia al WR-3D de una radiografía de miembros inferiores?","a":"Añade volumen 3D en carga para observar deformidades sagitales y transversales que una proyección puede ocultar por superposición o ángulo."},{"q":"¿Las funciones de IA y medición están incluidas?","a":"Dependen de los paquetes y series contratados. La configuración final debe especificar Cobb, HKA, torsión, flexión, segmentación y reportes."},{"q":"¿Puede estudiar la columna completa?","a":"Sí, el material Angell contempla escaneo y reconstrucción de columna completa, además de pelvis y miembros inferiores, con cobertura según el protocolo."},{"q":"¿El brochure es una ficha contractual?","a":"No. Es información genérica del fabricante; los equipos configurables pueden cambiar especificaciones, módulos y software. La referencia contractual es la cotización validada."}],"preguntas_frecuentes_en":[{"q":"How does WR-3D differ from lower-limb radiography?","a":"It adds weight-bearing 3D volume to reveal sagittal and transverse deformities that projection imaging can hide through overlap or angle."},{"q":"Are AI and measurement functions included?","a":"They depend on the contracted packages and series. The final configuration should specify Cobb, HKA, torsion, flexion, segmentation and reports."},{"q":"Can it image the full spine?","a":"Yes. Angell materials cover full-spine scanning and reconstruction, as well as pelvis and lower limbs, with protocol-dependent coverage."},{"q":"Is the brochure a contractual specification?","a":"No. It is generic manufacturer information; configurable equipment can change specifications, modules and software. The validated quotation is contractual."}],"seo_keywords_es":["radiografía 3D en carga WR-3D","CBCT de pie","escoliosis Cobb 3D","alineación de miembros inferiores","tomografía musculoesquelética Colombia"],"seo_keywords_en":["WR-3D weight-bearing radiography","standing CBCT","3D Cobb scoliosis","lower-limb alignment imaging","musculoskeletal tomography Colombia"]} $$::jsonb
WHERE slug IN ('sistema-radiografico-3d-wr-3d-angell-technology','sistema-radiografico-3d-wr-3d');
